import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"兰陵王·卷朱箔","description":"","frontmatter":{"title":"兰陵王·卷朱箔","date":"2026-11-14T00:00:00.000Z","seq":115,"categories":["美文","宋词三百首"],"collection":"《宋词三百首》","tags":["宋词三百首","宋"],"poem":true,"author":"张元干","source_book":"宋词三百首"},"headers":[],"relativePath":"blogs/宋词三百首/兰陵王·卷朱箔.md","filePath":"blogs/宋词三百首/兰陵王·卷朱箔.md"}'),o={name:"blogs/宋词三百首/兰陵王·卷朱箔.md"};function c(l,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="兰陵王·卷朱箔" tabindex="-1">兰陵王·卷朱箔 <a class="header-anchor" href="#兰陵王·卷朱箔" aria-label="Permalink to &quot;兰陵王·卷朱箔&quot;">​</a></h1><p class="poem-meta">宋 · 张元干</p><div class="poem"><p class="poem-stanza">卷朱箔。</p><p class="poem-stanza">朝雨轻阴乍阁。</p><p class="poem-stanza">阑干外，烟柳弄晴，芳草侵阶映红药。</p><p class="poem-stanza">东风妒花恶。</p><p class="poem-stanza">吹落。</p><p class="poem-stanza">梢头嫩萼。</p><p class="poem-stanza">屏山掩，沈水倦熏，中酒心情怕杯勺。</p><p class="poem-stanza">寻思旧京洛。</p><p class="poem-stanza">正年少疏狂，歌笑迷著。</p><p class="poem-stanza">障泥油壁催梳掠。</p><p class="poem-stanza">曾驰道同载，上林携手，灯夜初过早共约。</p><p class="poem-stanza">又争信漂泊。</p><p class="poem-stanza">寂寞。</p><p class="poem-stanza">念行乐。</p><p class="poem-stanza">甚粉淡衣襟，音断弦索。</p><p class="poem-stanza">琼枝璧月春如昨。</p><p class="poem-stanza">怅别后华表，那回双鹤。</p><p class="poem-stanza">相思除是，向醉里、暂忘却。</p></div>',3)])])}const d=s(o,[["render",c]]);export{z as __pageData,d as default};
